/**
 * Set of identity providers linked to a single MasterPlayer.
 * One player can be reachable through multiple channels (device, account, social) all mapping back to the same userId.
 * Each block is optional and only present when the player has actually linked the matching provider.
 */
export interface ExternalItem {
	/** Device-based identity (login by device id, no account registration required). */
	device?: {
		/** Custom device id generated by the client and uploaded by it (not tied to any specific platform). */
		customDeviceId?: string;
		/** Android device id (typically ANDROID_ID or Advertising ID). */
		androidDeviceId?: string;
		/** iOS device id (identifierForVendor or IDFA). */
		iOSDeviceId?: string;
		/** Windows Phone device id. */
		windowsPhoneDeviceId?: string;
		/** Windows desktop device id. */
		windowsDeviceId?: string;
		/** Linux device id. */
		linuxDeviceId?: string;
		/** macOS device id. */
		macOSDeviceId?: string;
		/** Editor device id (Unity Editor / dev mode) used for testing. */
		editorDeviceId?: string;
	};
	/** Username/password account that the player registered directly in the system. */
	account?: {
		/** Login username, unique across the whole system. */
		username: string;
		/** Hashed password (never plain text); checked by the verify routine on login. */
		password: string;
	};
	/** Login through a custom id minted by an external integration. */
	custom?: {
		/** Custom id issued to the player by the external integration. */
		customId: string;
	}
	/** Linked Sign in with Apple identity. */
	apple?: {
		/** Apple id (the `sub` claim in the identity token), a stable identifier of the Apple account. */
		appleId: string;
		/** Email returned by Apple (real address or private-relay alias). */
		email: string;
	};
	/** Linked Google Sign-In identity. */
	google?: {
		/** Google id-token `sub` claim — stable identifier of the Google account. */
		googleId: string;
		/** Display name supplied by Google. */
		displayName: string;
		/** Email of the Google account. */
		email: string;
	};
	/** Linked Facebook Login identity. */
	facebook?: {
		/** App-scoped Facebook user id. */
		facebookId: string;
		/** Display name pulled from the Facebook profile. */
		displayName: string;
		/** Email of the Facebook account (when the user grants the permission). */
		email: string;
	};
	/** Linked generic identity providers (extensions added by custom integrations). */
	genericService?: {
		/** Map of generic services: key is the service name, value holds the identity inside that service. */
		genericServices: Map<string, {
			/** Player identifier inside the corresponding generic service. */
			serviceId: string
		}>;
	};
	/** Linked Google Play Game Services identity (Android-specific). */
	googlePlayGameService?: {
		/** Player id issued by Google Play Games. */
		playerId: string,
		/** Email tied to the linked Play Games account. */
		email: string,
		/** Display name on Google Play Games. */
		displayName: string,
	};
	/** Linked Apple Game Center identity (iOS/macOS-specific). */
	gameCenter?: {
		/** Player id issued by Game Center. */
		playerId: string,
		/** Email tied to the Apple account linked with Game Center. */
		email: string,
		/** Display name on Game Center. */
		displayName: string,
	};
}
